import{_ as n,a0 as s,w as l,s as a,I as f,x as i,a1 as p,A as o,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"LibreOffice 和 OpenOffice 的相似與不同之處 | LCTT x X-CMD","titleTemplate":false,"description":"LibreOffice 和 OpenOffice 的相似與不同之處 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LibreOffice 和 OpenOffice 的相似與不同之處 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LibreOffice 和 OpenOffice 的相似與不同之處 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20220728 LibreOffice vs OpenOffice- All You Need to Know-","title":"LibreOffice 和 OpenOffice 的相似與不同之處","tag":"202308","desc":""},"relativePath":"202308/20220728 LibreOffice vs OpenOffice- All You Need to Know-.md","filePath":"[post].md"}'),O={name:"202308/20220728 LibreOffice vs OpenOffice- All You Need to Know-.md"};function b(m,e,d,u,c,L){const r=s("Link");return l(),a("div",null,[e[39]||(e[39]=f("h1",{id:"libreoffice-和-openoffice-的相似與不同之處",tabindex:"-1"},[i("LibreOffice 和 OpenOffice 的相似與不同之處 "),f("a",{class:"header-anchor",href:"#libreoffice-和-openoffice-的相似與不同之處","aria-label":"Permalink to “LibreOffice 和 OpenOffice 的相似與不同之處”"},"​")],-1)),e[40]||(e[40]=f("p",null,[f("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/10/143846kry5mmrmlll3bgql.jpg",alt:""})],-1)),e[41]||(e[41]=f("blockquote",null,[f("p",null,"對兩個最受歡迎的開源辦公軟件的比較。瞭解 LibreOffice 和 OpenOffice 之間的相似與不同之處。")],-1)),f("p",null,[e[1]||(e[1]=i("LibreOffice 與 OpenOffice 是兩個流行的微軟辦公套件的 ",-1)),p(r,{href:"https://itsfoss.com/best-free-open-source-alternatives-microsoft-office/"},{default:o(()=>[...e[0]||(e[0]=[i("開源替代品",-1)])]),_:1}),e[2]||(e[2]=i("。",-1))]),e[42]||(e[42]=t('<p>如果你正在尋找一個具備文字處理、電子表格、演示和其他幾個程序的開源辦公套件，那麼這兩個辦公軟件都可以推薦。</p><p>然而，要充分利用這些辦公套件，你應該瞭解它們之間的差異，以決定哪個最適合你。</p><p>你應該使用 LibreOffice 還是 OpenOffice？它們之間有什麼區別？在這裏，我將更詳細地探討這些問題。</p><h3 id="libreoffice-vs-openoffice-起源" tabindex="-1">LibreOffice vs. OpenOffice：起源 <a class="header-anchor" href="#libreoffice-vs-openoffice-起源" aria-label="Permalink to “LibreOffice vs. OpenOffice：起源”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-vs-openoffice.jpg" alt=""></p><p>OpenOffice 是由 <ruby>昇陽微系統<rt>Sun Microsystems</rt></ruby> 開發的項目。它是（他們最初收購的）與微軟辦公套件競爭的 StarOffice 的開源版本。</p><p>後來，<ruby>甲骨文<rt>Oracle</rt></ruby> 收購了昇陽微系統，並最終放棄了 OpenOffice.org（OOo），將代碼庫交給了 Apache。</p><p>在 Apache 開始維護它時，該辦公套件的名稱被更改為 “OpenOffice” 或 “Apache OpenOffice”。</p><p>在這個過渡期間，出於擔心 Oracle 會停止該項目，<ruby>文檔基金會<rt>The Document Foundation</rt></ruby> 復刻了 OpenOffice.org，創建了 LibreOffice。</p><p>因此，LibreOffice 是作為 OpenOffice.org 的替代品而創建的。</p><p>但是，現在 OpenOffice 仍然存在並得到積極維護（LCTT 譯註：不是），為什麼你應該選擇 LibreOffice？OpenOffice 不夠好嗎？它們之間有什麼相似之處？</p><h3 id="libreoffice-和-apache-openoffice-有什麼共同之處" tabindex="-1">LibreOffice 和 Apache OpenOffice 有什麼共同之處？ <a class="header-anchor" href="#libreoffice-和-apache-openoffice-有什麼共同之處" aria-label="Permalink to “LibreOffice 和 Apache OpenOffice 有什麼共同之處？”">​</a></h3><p>LibreOffice 和 Apache OpenOffice 有一些共同之處：</p><p>如果你只需要創建基本文檔、電子表格或演示文稿，並不需要進行任何複雜操作或快捷方式來提高生產力，那麼你可以使用它們中的任何一個。</p><p>簡單來説，如果你在 Linux、Windows 和 macOS 上需要一個開源辦公套件，這兩個軟件都可以勝任。</p><p>LibreOffice 和 Apache OpenOffice 都能夠打開包括微軟的 DOCX、PPT 等在內的各種文件格式。</p><p>但是，當你需要<strong>不同的功能、用户界面、文件格式兼容性、導出能力</strong>和其他特性時，它們之間的相似之處就會逐漸消失。</p><p>當然，如果你開始廣泛使用它們，你將會注意到它們之間的差異。</p><p>為了節省你的麻煩，讓我在這裏重點指出這些差異：</p><h3 id="安裝和平台可用性" tabindex="-1">安裝和平台可用性 <a class="header-anchor" href="#安裝和平台可用性" aria-label="Permalink to “安裝和平台可用性”">​</a></h3><p>用户體驗的第一步是安裝過程和平台可用性。</p><p>如果安裝複雜且不支持多個平台，那麼這個程序就令人失望。</p><p>在這種情況下，LibreOffice 和 Apache OpenOffice 官方支持 <strong>Linux、Windows 和 macOS</strong>。</p>',23)),f("p",null,[e[4]||(e[4]=i("至於移動平台，你可以在谷歌 Play 商店（安卓）和蘋果應用商店（iOS）上找到基於 LibreOffice 的 ",-1)),p(r,{href:"https://www.collaboraoffice.com/"},{default:o(()=>[...e[3]||(e[3]=[i("Collabora Office",-1)])]),_:1}),e[5]||(e[5]=i("。考慮到 Collabora 是 LibreOffice 的商業合作伙伴，它幾乎可以視為 LibreOffice 的官方移植版。",-1))]),e[43]||(e[43]=f("p",null,[i("而對於移動設備上的 OpenOffice，雖然你也可以使用其他社區/第三方移植版替代，"),f("strong",null,"但它沒有官方移植版可用"),i("。")],-1)),e[44]||(e[44]=f("p",null,"現在你已經瞭解了支持的平台，它們的安裝是否容易？",-1)),e[45]||(e[45]=f("p",null,[f("strong",null,"對於 Linux"),i("，LibreOffice 在官方軟件庫中可用，並在軟件中心和軟件包管理器中列出。因此，你只需點擊幾下即可在 Linux 系統上安裝它。")],-1)),e[46]||(e[46]=f("p",null,[f("img",{src:"https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-software-center.png",alt:"libreoffice software center"})],-1)),e[47]||(e[47]=f("p",null,"不幸的是，OpenOffice 的安裝過程比較麻煩。它不在軟件庫中，軟件中心中也找不到它。而且，如果你已經預先安裝了 LibreOffice，則在嘗試安裝 OpenOffice 之前必須先刪除任何痕跡（以避免安裝衝突）。",-1)),f("p",null,[e[7]||(e[7]=i("你需要從其網站下載官方軟件包（根據你的 Linux 發行版），然後解壓縮，並使用一些命令來",-1)),p(r,{href:"https://itsfoss.com/install-openoffice-ubuntu-linux/"},{default:o(()=>[...e[6]||(e[6]=[i("在 Linux 上安裝 OpenOffice",-1)])]),_:1}),e[8]||(e[8]=i("。",-1))]),e[48]||(e[48]=f("p",null,[f("img",{src:"https://itsfoss.com/content/images/wordpress/2022/07/openoffice-debs-linux.png",alt:"openoffice debs linux"})],-1)),f("p",null,[e[10]||(e[10]=f("strong",null,"對於 Windows 和 macOS",-1)),e[11]||(e[11]=i("，安裝非常簡單，你只需 ",-1)),p(r,{href:"https://www.libreoffice.org/download/download/"},{default:o(()=>[...e[9]||(e[9]=[i("下載安裝包",-1)])]),_:1}),e[12]||(e[12]=i("，然後按照屏幕上的指示進行操作即可。",-1))]),f("p",null,[p(r,{href:"https://www.libreoffice.org/download/libreoffice-from-microsoft-and-mac-app-stores/"},{default:o(()=>[...e[13]||(e[13]=[i("LibreOffice 還提供了另一種方式",-1)])]),_:1}),e[14]||(e[14]=i(" 可供獲取（通過合作伙伴），即通過微軟商店和 Mac 應用商店。不過，你需要支付費用。其中的一部分將捐贈給文檔基金會，一部分用於 LibreOffice 的開發。",-1))]),f("p",null,[e[16]||(e[16]=i("還要注意，由於 ",-1)),p(r,{href:"https://www.collaboraoffice.com/press-releases/collabora-office-ships-for-chromebooks/"},{default:o(()=>[...e[15]||(e[15]=[i("Collabora Office",-1)])]),_:1}),e[17]||(e[17]=i("，你也可以在 Chromebook 上使用 LibreOffice。",-1))]),e[49]||(e[49]=t('<p><strong>總而言之，LibreOffice 提供了更好的平台可用性和更輕鬆的安裝過程，這使得 OpenOffice 成為一個不太推薦的選擇。</strong></p><h3 id="用户體驗" tabindex="-1">用户體驗 <a class="header-anchor" href="#用户體驗" aria-label="Permalink to “用户體驗”">​</a></h3><p>LibreOffice 提供了一個令人愉悦的用户界面，與現代標準相融合。LibreOffice 在大多數現代硬件上看起來都很好，不論你使用的是 2K 顯示器還是 4K 顯示器。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-home-1.png" alt="libreoffice home 1"></p><p>你可以從主啓動器快速訪問所有工具，這是一種良好的體驗。Writer、Calc 和其他程序提供了一個易於使用且看起來井然有序的界面。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-writer.png" alt="libreoffice writer"></p><p>Apache OpenOffice 提供的是一個過時的用户界面。因此，如果你正在尋找一個現代化的開源辦公套件，LibreOffice 是首選。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/openoffice-home.png" alt="openoffice home"></p><p>當然，一些用户喜歡經典的用户界面，因為他們對此很熟悉，並且在舊硬件上的使用受到限制。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/openoffice-writer.png" alt="openoffice writer"></p><p>換句話説，OpenOffice 仍然可用，但對於大多數現代用户來説可能不是一種直觀的體驗。</p><p>如果你仔細比較用户界面元素，這將取決於你閲讀本文時可用的最新版本。因此，我們避免進行具體的視覺比較。</p><h3 id="特點" tabindex="-1">特點 <a class="header-anchor" href="#特點" aria-label="Permalink to “特點”">​</a></h3><p>強大的功能集的需求取決於你處理的文件類型。</p><p>默認情況下，OpenOffice 和 LibreOffice 均提供以下程序：</p><ul><li>Math（科學公式）</li><li>Writer（文檔）</li><li>Impress（演示文稿）</li><li>Draw（繪圖、流程圖等）</li><li>Calc（電子表格）</li><li>Base（資料庫）</li></ul><p>無論你使用文字處理器（Writer）、電子表格（Calc）還是演示文稿（Impress），你都可以獲得相同的標準功能。</p><p>然而，如果你處理需要訪問<strong>更多模板、函數、導入/導出選項和高級格式設置</strong>的複雜文檔，LibreOffice 會更優秀一些。</p><h3 id="文件格式兼容性" tabindex="-1">文件格式兼容性 <a class="header-anchor" href="#文件格式兼容性" aria-label="Permalink to “文件格式兼容性”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/file-format-illustration.jpg" alt=""></p><p>OpenOffice 支持幾乎與 LibreOffice 相同的文件擴展名。</p><p>但是，LibreOffice 還支持一些 OpenOffice 不支持的文件格式導出。</p><p>例如，你可以在 OpenOffice 中打開 <strong>.DOCX</strong> 文件，但無法保留文件擴展名保存/導出該文件。</p><p>你只能將其保存為 .odt/.doc./.ott 等幾種類似的文件格式。</p><p>同樣，你無法得到對 .xslx 和 .pptx 的支持，這些是通常用於電子表格和演示文稿的現代文件格式。</p><p>當然，如果你不依賴於這些文件格式，可以嘗試使用 OpenOffice。然而，與使用較新文件格式的用户進行協作時，你將遇到可能影響你工作的兼容性/格式設置問題。</p><p>考慮到 OpenOffice 缺乏許多功能，依賴它來訪問較新的文件格式可能不明智；由於不良的兼容性，你可能會丟失重要的細節。</p><h3 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/software-update-illustration.jpg" alt=""></p><p>為了提高你使用該程序的效率並獲得增強的性能、新功能和安全修復，建議選擇定期獲得更新的軟件工具。</p><p>從技術上講，兩者都會定期獲得更新。但是，OpenOffice 僅限於修復錯誤和進行小型更新。</p><p>LibreOffice 的開發活動更加活躍，頻繁修復錯誤/進行小型更新，定期進行較大的升級，增加新功能和改善用户體驗。</p>',32)),f("p",null,[e[19]||(e[19]=i("難怪 ",-1)),p(r,{href:"https://itsfoss.com/libreoffice-letter-openoffice/"},{default:o(()=>[...e[18]||(e[18]=[i("LibreOffice 給 Apache 寫了一封公開信",-1)])]),_:1}),e[20]||(e[20]=i("，請求停止開發 OpenOffice 並將這些資源轉用於幫助 LibreOffice 的開發。",-1))]),e[50]||(e[50]=f("h3",{id:"企業支持和在線協作選項",tabindex:"-1"},[i("企業支持和在線協作選項 "),f("a",{class:"header-anchor",href:"#企業支持和在線協作選項","aria-label":"Permalink to “企業支持和在線協作選項”"},"​")],-1)),e[51]||(e[51]=f("p",null,[f("img",{src:"https://itsfoss.com/content/images/wordpress/2022/07/enterprise-illustration.jpg",alt:""})],-1)),f("p",null,[e[23]||(e[23]=i("有了 ",-1)),p(r,{href:"https://www.collaboraoffice.com/"},{default:o(()=>[...e[21]||(e[21]=[i("Collabora Office",-1)])]),_:1}),e[24]||(e[24]=i("，你可以獲得企業支持，並能夠在工作場所使用 LibreOffice。通過 ",-1)),p(r,{href:"https://www.collaboraoffice.com/collabora-online/"},{default:o(()=>[...e[22]||(e[22]=[i("Collabora Online",-1)])]),_:1}),e[25]||(e[25]=i("，你還可以在服務器上部署 LibreOffice 以實現協作工作空間。",-1))]),e[52]||(e[52]=t('<p>遺憾的是，Apache OpenOffice 沒有任何企業支持選項。因此，如果有的話，它最適合家庭用户使用。</p><h3 id="許可" tabindex="-1">許可 <a class="header-anchor" href="#許可" aria-label="Permalink to “許可”">​</a></h3><p>對於使用這些程序並無任何許可問題，也不會阻止或使你不願使用它們。然而，這些信息對於項目的貢獻者可能會有所幫助。</p><p>LibreOffice 使用 Mozilla Public License v2.0 許可證，而 Apache OpenOffice 則使用 Apache License 2.0 許可證。</p><h3 id="libreoffice-vs-openoffice-應該選擇哪個" tabindex="-1">LibreOffice vs. OpenOffice：應該選擇哪個？ <a class="header-anchor" href="#libreoffice-vs-openoffice-應該選擇哪個" aria-label="Permalink to “LibreOffice vs. OpenOffice：應該選擇哪個？”">​</a></h3><p>基於現代設計、更多功能和對較新文件格式的支持，LibreOffice 是一個易於推薦的選擇。</p><p>OpenOffice 可以是適用於熟悉舊版辦公套件界面，且希望在 32 位系統中無障礙運行的用户的解決方案。在 LibreOffice 由於某些原因無法正常工作的情況下，OpenOffice 應該作為備選方案。</p><p>我們可以告訴你選擇取決於個人喜好，但如果你經常處理文檔，如果我不説 LibreOffice 是更好的選擇，那麼我顯然不夠誠懇。</p><p><em>（題圖：MJ/52f9aa1b-3529-492a-a5fb-7b24b62e2e8a）</em></p><hr>',10)),f("p",null,[e[27]||(e[27]=i("via: ",-1)),p(r,{href:"https://itsfoss.com/libreoffice-vs-openoffice/"},{default:o(()=>[...e[26]||(e[26]=[i("https://itsfoss.com/libreoffice-vs-openoffice/",-1)])]),_:1})]),f("p",null,[e[31]||(e[31]=i("作者：",-1)),p(r,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...e[28]||(e[28]=[i("Ankush Das",-1)])]),_:1}),e[32]||(e[32]=i(" 選題：",-1)),p(r,{href:"https://github.com/lkxed"},{default:o(()=>[...e[29]||(e[29]=[i("lkxed",-1)])]),_:1}),e[33]||(e[33]=i(" 譯者：ChatGPT 校對：",-1)),p(r,{href:"https://github.com/wxy"},{default:o(()=>[...e[30]||(e[30]=[i("wxy",-1)])]),_:1})]),f("p",null,[e[36]||(e[36]=i("本文由 ",-1)),p(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[34]||(e[34]=[i("LCTT",-1)])]),_:1}),e[37]||(e[37]=i(" 原創編譯，",-1)),p(r,{href:"https://linux.cn/"},{default:o(()=>[...e[35]||(e[35]=[i("Linux中國",-1)])]),_:1}),e[38]||(e[38]=i(" 榮譽推出",-1))])])}const x=n(O,[["render",b]]);export{T as __pageData,x as default};
